 */
export function buildCodexExecArgs(input) {
  const extra = input.extra ?? {};
  const cliModel = extra.cliModel ?? null;
  const reasoningEffort = extra.reasoningEffort ?? null;
  const verbosity = extra.verbosity ?? null;

